// Coding pipeline view: bugs/features/auto CODING items (tasks/ideas with
// issue_kind, target_repo, an implement route, or the autogenerated tag) in
// one lifecycle — inbox → approved → implementation → done — separate from the
// per-type Board. Reuses the mini-DOM approach of planningDashboardRender.test.ts.
import { describe, it, expect } from "vitest";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { runInNewContext } from "node:vm";

const src = readFileSync(resolve(__dirname, "../../media/planning-dashboard.js"), "utf8");

type El = {
  tagName: string;
  id: string;
  className: string;
  children: El[];
  parent: El | null;
  dataset: Record<string, string>;
  attrs: Record<string, string>;
  style: Record<string, string>;
  textContent: string;
  value: string;
  title: string;
  focus: () => void;
  innerHTML: string;
  selected?: boolean;
  draggable?: boolean;
  listeners: Record<string, Array<(ev: FakeEvent) => void>>;
  classList: { add: (...c: string[]) => void; remove: (...c: string[]) => void; toggle: (c: string, on?: boolean) => void; contains: (c: string) => boolean };
  appendChild: (c: El) => El;
  insertBefore: (c: El, ref: El | null) => El;
  addEventListener: (t: string, fn: (...a: unknown[]) => void) => void;
  querySelector: (sel: string) => El | null;
  querySelectorAll: (sel: string) => El[];
  closest: (sel: string) => El | null;
  setAttribute: (k: string, v: string) => void;
  getAttribute: (k: string) => string | null;
};

type FakeEvent = {
  type: string;
  target: El | { value?: string };
  preventDefault: () => void;
  stopPropagation: () => void;
  shiftKey?: boolean;
  ctrlKey?: boolean;
  metaKey?: boolean;
  dataTransfer?: {
    setData: (k: string, v: string) => void;
    getData: (k: string) => string;
    effectAllowed?: string;
  };
};

function miniDom(snapshot: unknown, state: Record<string, unknown>, initialView?: string, sessions?: unknown[]) {
  const byId = new Map<string, El>();
  const posted: Array<Record<string, unknown>> = [];

  function matches(el: El, sel: string): boolean {
    const s = sel.trim();
    if (s.startsWith("#")) return el.id === s.slice(1);
    if (s.startsWith(".")) return el.className.split(/\s+/).includes(s.slice(1));
    return el.tagName === s.toUpperCase();
  }
  function walk(el: El, acc: El[] = []): El[] {
    acc.push(el);
    for (const c of el.children) walk(c, acc);
    return acc;
  }

  function create(tag: string): El {
    const el: El = {
      tagName: tag.toUpperCase(),
      id: "",
      className: "",
      children: [],
      parent: null,
      dataset: {},
      attrs: {},
      style: {},
      textContent: "",
      value: "",
      title: "",
      innerHTML: "",
      focus: () => {},
      listeners: {},
      classList: {
        add: (...c: string[]) => {
          el.className = [...new Set((el.className || "").split(/\s+/).filter(Boolean).concat(c))].join(" ");
        },
        remove: (...c: string[]) => {
          el.className = (el.className || "").split(/\s+/).filter((x) => x && !c.includes(x)).join(" ");
        },
        toggle: (c: string, on?: boolean) => {
          const has = el.classList.contains(c);
          const should = on === undefined ? !has : on;
          if (should) el.classList.add(c);
          else el.classList.remove(c);
        },
        contains: (c: string) => (el.className || "").split(/\s+/).includes(c),
      },
      appendChild(c: El) {
        c.parent = el;
        el.children.push(c);
        if (c.id) byId.set(c.id, c);
        return c;
      },
      insertBefore(c: El, ref: El | null) {
        c.parent = el;
        const i = ref ? el.children.indexOf(ref) : -1;
        if (i >= 0) el.children.splice(i, 0, c);
        else el.children.push(c);
        if (c.id) byId.set(c.id, c);
        return c;
      },
      addEventListener(t: string, fn: (...a: unknown[]) => void) {
        (el.listeners[t] ||= []).push(fn as (ev: FakeEvent) => void);
      },
      querySelector(sel: string) {
        return el.querySelectorAll(sel)[0] || null;
      },
      querySelectorAll(sel: string) {
        const parts = sel.trim().split(/\s+/);
        return walk(el).slice(1).filter((n) => {
          let node: El | null = n;
          for (let i = parts.length - 1; i >= 0; i--) {
            while (node && !matches(node, parts[i])) {
              if (i === parts.length - 1) return false;
              node = node.parent;
            }
            if (!node) return false;
            if (i > 0) node = node.parent;
          }
          return true;
        });
      },
      closest(sel: string) {
        let n: El | null = el;
        while (n) {
          if (matches(n, sel)) return n;
          n = n.parent;
        }
        return null;
      },
      setAttribute(k: string, v: string) {
        if (k === "id") {
          el.id = v;
          byId.set(v, el);
        }
        if (k === "class") el.className = v;
        el.attrs[k] = v;
        if (k.startsWith("data-")) el.dataset[k.slice(5)] = v;
      },
      getAttribute(k: string) {
        if (k === "id") return el.id || null;
        if (k === "class") return el.className || null;
        return k in el.attrs ? el.attrs[k] : null;
      },
    };
    Object.defineProperty(el, "innerHTML", {
      get() {
        return (el as unknown as { _html?: string })._html || "";
      },
      set(html: string) {
        (el as unknown as { _html?: string })._html = html;
        el.textContent = String(html).replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim();
        el.children = [];
        const re = /<([a-zA-Z0-9]+)([^>]*)>/g;
        let m: RegExpExecArray | null;
        while ((m = re.exec(html))) {
          const child = create(m[1]);
          const id = /id="([^"]+)"/.exec(m[2]);
          const cls = /class="([^"]+)"/.exec(m[2]);
          if (id) {
            child.id = id[1];
            byId.set(id[1], child);
          }
          if (cls) child.className = cls[1];
          const did = /data-id="([^"]+)"/.exec(m[2]);
          if (did) child.dataset.id = did[1];
          const dlane = /data-lane="([^"]+)"/.exec(m[2]);
          if (dlane) child.dataset.lane = dlane[1];
          for (const am of m[2].matchAll(/([a-zA-Z0-9-]+)="([^"]*)"/g)) {
            child.attrs[am[1]] = am[2];
            if (am[1].startsWith("data-")) child.dataset[am[1].slice(5)] = am[2];
          }
          el.appendChild(child);
        }
      },
    });
    return el;
  }

  const body = create("body");
  const ids = [
    "board", "pipeline", "issues", "counts", "overduePill", "inboxPill", "loadOverlay", "loadTitle", "loadDetail",
    "loadTime", "loadRetry", "loadSpin", "viewSeg", "laneSeg", "calModeSeg", "groupBy",
    "sortBy", "addLaneBtn", "inbox", "autonomous", "projects", "sessions", "social",
    "calendar", "graph", "gfilters", "canvas", "backdrop", "drawer", "drawerInner",
    "resmodal", "resTitle", "resSub", "resWarn", "resNote", "resSave", "resSkip", "resCancel",
    "resX", "search", "syncPill", "captureBtn", "refreshBtn", "syncBtn", "topbar", "main",
  ];
  for (const id of ids) {
    const el = create("div");
    el.id = id;
    if (id === "board") el.className = "view";
    body.appendChild(el);
    byId.set(id, el);
  }

  const windowObj: Record<string, unknown> = {
    __paintTried: false,
    addEventListener: (type: string, fn: (...a: unknown[]) => void) => {
      if (type !== "message") return;
      const send = fn as (e: { data: unknown }) => void;
      send({ data: { type: "snapshot", data: snapshot } });
      if (sessions) send({ data: { type: "sessions", data: sessions } });
      if (initialView) send({ data: { type: "setView", view: initialView } });
    },
  };
  const document = {
    body,
    createElement: (tag: string) => create(tag),
    getElementById: (id: string) => byId.get(id) || null,
    querySelector: (sel: string) => {
      const s = sel.trim();
      if (/^#[\w-]+$/.test(s)) return byId.get(s.slice(1)) || null;
      return body.querySelector(s);
    },
    querySelectorAll: (sel: string) => {
      const s = sel.trim();
      if (/^#[\w-]+$/.test(s)) {
        const n = byId.get(s.slice(1));
        return n ? [n] : [];
      }
      return body.querySelectorAll(s);
    },
    addEventListener: () => {},
  };

  const sandbox = {
    acquireVsCodeApi: () => ({
      postMessage: (m: Record<string, unknown>) => posted.push(m),
      getState: () => state,
      setState: () => {},
    }),
    document,
    window: windowObj,
    setInterval: () => 0,
    setTimeout: (fn: () => void) => {
      fn();
      return 0;
    },
    clearTimeout: () => {},
    clearInterval: () => {},
    Date,
    Set,
    Map,
    JSON,
    Number,
    String,
    Math,
    Array,
    Object,
    console,
  };
  (sandbox.window as { document: typeof document }).document = document;
  return { sandbox, byId, posted, fire };
}

function fire(el: El, type: string, init: Partial<FakeEvent> = {}): FakeEvent {
  const store: Record<string, string> = {};
  const ev: FakeEvent = {
    type,
    target: el,
    preventDefault() {},
    stopPropagation() {},
    shiftKey: false,
    ctrlKey: false,
    metaKey: false,
    dataTransfer: {
      setData(k: string, v: string) { store[k] = v; },
      getData(k: string) { return store[k] || ""; },
      effectAllowed: "",
    },
    ...init,
  };
  if (init.dataTransfer) ev.dataTransfer = init.dataTransfer;
  for (const fn of el.listeners[type] || []) fn(ev);
  return ev;
}

const snapshot = {
  objects: [
    { id: "tasks/fresh", type: "task", status: "inbox", title: "Fresh bug", issue_kind: "bug" },
    { id: "ideas/auto1", type: "idea", status: "capture", title: "Night idea", tags: '["autogenerated"]' },
    { id: "ideas/appr", type: "idea", status: "capture", title: "Approved idea", auto_implement: "ready", implement_backend: "grok", implement_model: "grok-4.6" },
    { id: "tasks/appr2", type: "task", status: "today", title: "Approved task", target_repo: "code-build-vscode" },
    { id: "tasks/wip", type: "task", status: "in_progress", title: "Being built", issue_kind: "feature" },
    { id: "ideas/running", type: "idea", status: "capture", title: "Running now", linked_sessions: '["sess-linked"]' },
    { id: "tasks/shipped", type: "task", status: "done", title: "Shipped", target_repo: "knowledge-planning", updated: new Date().toISOString().slice(0, 10) },
    // non-coding items — must stay OFF the coding pipeline
    { id: "tasks/errand", type: "task", status: "today", title: "Buy groceries" },
    { id: "thoughts/note", type: "thought", status: "new", title: "A thought" },
    { id: "plans/big", type: "plan", status: "implement", title: "Life plan" },
  ],
  counts: { task: 5, idea: 3, thought: 1, plan: 1 },
  blocked: [],
  board: { date: "2026-09-02" },
  autonomous: {
    enabled: true,
    current_window: {
      start: new Date().toISOString(),
      end: new Date(Date.now() + 3600_000).toISOString(),
      ideate: { status: "done" },
      implement: { status: "running", item: "ideas/running", session: "sess-plan" },
    },
  },
};

function lanesOf(byId: Map<string, El>, container = "pipeline"): Record<string, El> {
  const board = byId.get(container)!;
  const out: Record<string, El> = {};
  for (const col of board.querySelectorAll(".col")) out[col.dataset.lane!] = col;
  return out;
}
function cardIds(col: El): string[] {
  return col.querySelectorAll(".card").map((c) => c.dataset.id!);
}

describe("coding pipeline view", () => {
  it("paints the four lifecycle lanes with coding items only (bugs/auto/approved/running/done)", () => {
    const { sandbox, byId } = miniDom(snapshot, {}, "pipeline");
    expect(() => runInNewContext(src, sandbox, { filename: "planning-dashboard.js" })).not.toThrow();
    const lanes = lanesOf(byId);
    expect(Object.keys(lanes)).toEqual(["inbox", "approved", "implementation", "done"]);
    expect(cardIds(lanes.inbox).sort()).toEqual(["ideas/auto1", "tasks/fresh"]);
    expect(cardIds(lanes.approved).sort()).toEqual(["ideas/appr", "tasks/appr2"]);
    // running item is pulled into implementation by plan.json even at status=capture
    expect(cardIds(lanes.implementation).sort()).toEqual(["ideas/running", "tasks/wip"]);
    expect(cardIds(lanes.done)).toEqual(["tasks/shipped"]);
    // non-coding items (personal task / thought / plan) never enter the pipeline
    const all = Object.values(lanes).flatMap((l) => cardIds(l));
    expect(all).not.toContain("tasks/errand");
    expect(all).not.toContain("thoughts/note");
    expect(all).not.toContain("plans/big");
  });

  it("renders kind/auto/route chips and a session-opening running chip", () => {
    const { sandbox, byId } = miniDom(snapshot, {}, "pipeline");
    runInNewContext(src, sandbox, { filename: "planning-dashboard.js" });
    const lanes = lanesOf(byId);
    const bug = lanes.inbox.querySelectorAll(".card").find((c) => c.dataset.id === "tasks/fresh")!;
    expect(bug.innerHTML).toContain("🐛 bug");
    const auto = lanes.inbox.querySelectorAll(".card").find((c) => c.dataset.id === "ideas/auto1")!;
    expect(auto.innerHTML).toContain("🤖");
    const routed = lanes.approved.querySelectorAll(".card").find((c) => c.dataset.id === "ideas/appr")!;
    expect(routed.innerHTML).toContain("grok · grok-4.6");
    const running = lanes.implementation.querySelectorAll(".card").find((c) => c.dataset.id === "ideas/running")!;
    expect(running.innerHTML).toContain("▶ implementing");
    expect(running.innerHTML).toContain('data-sess="sess-plan"'); // plan.json session wins over linked_sessions
  });

  it("ignores a stale running marker from a window that ended long ago", () => {
    const stale = JSON.parse(JSON.stringify(snapshot));
    stale.autonomous.current_window.end = new Date(Date.now() - 7200_000).toISOString();
    const { sandbox, byId } = miniDom(stale, {}, "pipeline");
    runInNewContext(src, sandbox, { filename: "planning-dashboard.js" });
    const lanes = lanesOf(byId);
    expect(cardIds(lanes.implementation)).toEqual(["tasks/wip"]);
    // no live run → ideas/running has no coding marker at all → off the pipeline
    const all = Object.values(lanes).flatMap((l) => cardIds(l));
    expect(all).not.toContain("ideas/running");
  });

  it("quick-filters by kind (bug / feature / auto)", () => {
    const bugs = miniDom(snapshot, { pipeKind: "bug" }, "pipeline");
    runInNewContext(src, bugs.sandbox, { filename: "planning-dashboard.js" });
    let all = Object.values(lanesOf(bugs.byId)).flatMap((l) => cardIds(l));
    expect(all).toEqual(["tasks/fresh"]);
    const auto = miniDom(snapshot, { pipeKind: "auto" }, "pipeline");
    runInNewContext(src, auto.sandbox, { filename: "planning-dashboard.js" });
    all = Object.values(lanesOf(auto.byId)).flatMap((l) => cardIds(l));
    expect(all).toEqual(["ideas/auto1"]);
    const feats = miniDom(snapshot, { pipeKind: "feature" }, "pipeline");
    runInNewContext(src, feats.sandbox, { filename: "planning-dashboard.js" });
    all = Object.values(lanesOf(feats.byId)).flatMap((l) => cardIds(l));
    expect(all).toEqual(["tasks/wip"]);
  });

  it("filters by project and by worked-on window", () => {
    const withProj = JSON.parse(JSON.stringify(snapshot));
    withProj.objects.forEach((o: any) => {
      if (o.id === "tasks/fresh") { o.project = "projects/code-build"; o.updated = new Date().toISOString().slice(0, 10); }
      if (o.id === "ideas/auto1") { o.project = "projects/kp"; o.updated = "2020-01-01"; }
    });
    const proj = miniDom(withProj, { pipeProject: "projects/code-build" }, "pipeline");
    runInNewContext(src, proj.sandbox, { filename: "planning-dashboard.js" });
    let all = Object.values(lanesOf(proj.byId)).flatMap((l) => cardIds(l));
    expect(all).toEqual(["tasks/fresh"]);
    // week window: tasks/fresh updated today stays; ideas/auto1 from 2020 drops
    const win = miniDom(withProj, { pipeWindow: "week" }, "pipeline");
    runInNewContext(src, win.sandbox, { filename: "planning-dashboard.js" });
    all = Object.values(lanesOf(win.byId)).flatMap((l) => cardIds(l));
    expect(all).toContain("tasks/fresh");
    expect(all).not.toContain("ideas/auto1");
  });

  it("groups cards by project within a lane when ⫶ by project is on", () => {
    const withProj = JSON.parse(JSON.stringify(snapshot));
    withProj.objects.forEach((o: any) => {
      if (o.id === "tasks/fresh") o.project = "projects/code-build";
      if (o.id === "ideas/auto1") o.project = "projects/kp";
    });
    const { sandbox, byId } = miniDom(withProj, { pipeGroupProj: true }, "pipeline");
    runInNewContext(src, sandbox, { filename: "planning-dashboard.js" });
    const inbox = lanesOf(byId).inbox;
    const heads = inbox.querySelectorAll(".planehead").map((h) => h.innerHTML);
    expect(heads).toEqual(["⫶ code-build", "⫶ kp"]);
  });

  it("keeps the Board on classic per-type status lanes (default task lane-set)", () => {
    const { sandbox, byId } = miniDom(snapshot, {});
    runInNewContext(src, sandbox, { filename: "planning-dashboard.js" });
    const lanes = lanesOf(byId, "board");
    expect(Object.keys(lanes)).toEqual(["inbox", "today", "in_progress", "done", "deferred", "outdated"]);
    // the Board still shows ALL tasks, including non-coding ones
    expect(cardIds(lanes.today)).toContain("tasks/errand");
  });

  it("paints a default route picker (provider · model · effort) on the pipeline filter bar", () => {
    const { sandbox, byId } = miniDom(snapshot, {}, "pipeline");
    runInNewContext(src, sandbox, { filename: "planning-dashboard.js" });
    expect(byId.get("ppProv")).toBeTruthy();
    expect(byId.get("ppModel")).toBeTruthy();
    expect(byId.get("ppEffort")).toBeTruthy();
    // options filled from IMPL_PROV / IMPL_EFF
    const provVals = (byId.get("ppProv")!.children || []).map((c) => c.value);
    expect(provVals).toContain("claude");
    expect(provVals).toContain("grok");
  });

  it("changing the pipeline route posts setImplPrefs for grok and for claude", () => {
    const { sandbox, byId, posted } = miniDom(snapshot, {}, "pipeline");
    runInNewContext(src, sandbox, { filename: "planning-dashboard.js" });
    const prov = byId.get("ppProv")!;
    const model = byId.get("ppModel")!;
    const effort = byId.get("ppEffort")!;
    prov.value = "grok";
    fire(prov, "change");
    expect(model.children.map((c) => c.value)).toEqual(["", "default", "grok-4.6", "grok-4.5", "grok-code-fast-1"]);
    model.value = "grok-4.6";
    fire(model, "change");
    effort.value = "high";
    fire(effort, "change");
    let msg = [...posted].reverse().find((m) => m.action === "setImplPrefs");
    expect(msg).toMatchObject({ backend: "grok", model: "grok-4.6", effort: "high" });
    prov.value = "claude";
    fire(prov, "change");
    expect(model.children.map((c) => c.value)).toEqual(["", "default", "fable", "opus", "sonnet", "haiku"]);
    model.value = "fable";
    fire(model, "change");
    effort.value = "medium";
    fire(effort, "change");
    msg = [...posted].reverse().find((m) => m.action === "setImplPrefs");
    expect(msg).toMatchObject({ backend: "claude", model: "fable", effort: "medium" });
  });

  it("each pipeline lane header has a select-all control", () => {
    const { sandbox, byId } = miniDom(snapshot, {}, "pipeline");
    runInNewContext(src, sandbox, { filename: "planning-dashboard.js" });
    const lanes = lanesOf(byId);
    for (const col of Object.values(lanes)) {
      const btn = col.querySelector(".laneselect");
      expect(btn).toBeTruthy();
    }
  });

  it("ctrl-click toggles card selection without opening the drawer", () => {
    const { sandbox, byId, posted } = miniDom(snapshot, {}, "pipeline");
    runInNewContext(src, sandbox, { filename: "planning-dashboard.js" });
    const lanes = lanesOf(byId);
    const a = lanes.inbox.querySelectorAll(".card").find((c) => c.dataset.id === "tasks/fresh")!;
    const b = lanes.inbox.querySelectorAll(".card").find((c) => c.dataset.id === "ideas/auto1")!;
    fire(a, "click", { ctrlKey: true, target: a });
    fire(b, "click", { ctrlKey: true, target: b });
    expect(a.classList.contains("selected")).toBe(true);
    expect(b.classList.contains("selected")).toBe(true);
    expect(posted.some((m) => m.type === "show")).toBe(false);
  });

  it("shift-click selects a range within a lane", () => {
    const { sandbox, byId } = miniDom(snapshot, {}, "pipeline");
    runInNewContext(src, sandbox, { filename: "planning-dashboard.js" });
    const inbox = lanesOf(byId).inbox;
    const cards = inbox.querySelectorAll(".card");
    expect(cards.length).toBeGreaterThanOrEqual(2);
    fire(cards[0], "click", { ctrlKey: true, target: cards[0] });
    fire(cards[cards.length - 1], "click", { shiftKey: true, target: cards[cards.length - 1] });
    expect(cards.every((c) => c.classList.contains("selected"))).toBe(true);
  });

  it("lane select-all after search only selects visible cards", () => {
    const { sandbox, byId } = miniDom(snapshot, {}, "pipeline");
    runInNewContext(src, sandbox, { filename: "planning-dashboard.js" });
    const search = byId.get("search")!;
    search.value = "Fresh";
    fire(search, "input", { target: search });
    const inbox = lanesOf(byId).inbox;
    const cards = inbox.querySelectorAll(".card");
    const fresh = cards.find((c) => c.dataset.id === "tasks/fresh")!;
    const auto = cards.find((c) => c.dataset.id === "ideas/auto1")!;
    expect(fresh.style.display).not.toBe("none");
    expect(auto.style.display).toBe("none");
    const selAll = inbox.querySelector(".laneselect")!;
    fire(selAll, "click", { target: selAll });
    expect(fresh.classList.contains("selected")).toBe(true);
    expect(auto.classList.contains("selected")).toBe(false);
  });

  function setRoute(byId: Map<string, El>, backend: string, mdl: string, effort: string) {
    const prov = byId.get("ppProv")!;
    const model = byId.get("ppModel")!;
    const pe = byId.get("ppEffort")!;
    prov.value = backend;
    fire(prov, "change");
    model.value = mdl;
    fire(model, "change");
    pe.value = effort;
    fire(pe, "change");
  }

  it("dragging a multi-selection onto implementation posts grok route", () => {
    const { sandbox, byId, posted } = miniDom(snapshot, {}, "pipeline");
    runInNewContext(src, sandbox, { filename: "planning-dashboard.js" });
    setRoute(byId, "grok", "grok-4.6", "high");
    const lanes = lanesOf(byId);
    const a = lanes.inbox.querySelectorAll(".card").find((c) => c.dataset.id === "tasks/fresh")!;
    const b = lanes.inbox.querySelectorAll(".card").find((c) => c.dataset.id === "ideas/auto1")!;
    fire(a, "click", { ctrlKey: true, target: a });
    fire(b, "click", { ctrlKey: true, target: b });
    const start = fire(a, "dragstart", { target: a });
    const payload = start.dataTransfer!.getData("text/plain");
    expect(payload.split("\n").sort()).toEqual(["ideas/auto1", "tasks/fresh"]);
    fire(lanes.implementation, "drop", {
      target: lanes.implementation,
      dataTransfer: { setData() {}, getData() { return payload; } },
    });
    const move = posted.find((m) => m.action === "pipelineMove");
    expect(move).toMatchObject({
      lane: "implementation",
      route: { backend: "grok", model: "grok-4.6", effort: "high" },
    });
    expect((move!.ids as string[]).sort()).toEqual(["ideas/auto1", "tasks/fresh"]);
  });

  it("dragging onto implementation with Claude route posts claude · fable · medium", () => {
    const { sandbox, byId, posted } = miniDom(snapshot, {}, "pipeline");
    runInNewContext(src, sandbox, { filename: "planning-dashboard.js" });
    setRoute(byId, "claude", "fable", "medium");
    const lanes = lanesOf(byId);
    const a = lanes.inbox.querySelectorAll(".card").find((c) => c.dataset.id === "tasks/fresh")!;
    fire(a, "dragstart", { target: a });
    fire(lanes.implementation, "drop", {
      target: lanes.implementation,
      dataTransfer: { setData() {}, getData() { return "tasks/fresh"; } },
    });
    const move = posted.find((m) => m.action === "pipelineMove");
    expect(move).toMatchObject({
      lane: "implementation",
      ids: ["tasks/fresh"],
      route: { backend: "claude", model: "fable", effort: "medium" },
    });
  });
});

